const FESTIVALS=[{id:"carnaval-ha-long",n:"Carnaval Hạ Long",t:"a",g:"khac",p:"Quảng trường 30/10 và đường Trần Quốc Nghiễn",s:"Lễ hội đường phố của Quảng Ninh vào dịp 30/4, gồm đoàn diễu diễn dọc đường Trần Quốc Nghiễn và chương trình nghệ thuật tại Quảng trường 30/10.",y:{2026:"2026-04-30"}},{id:"cho-vieng",n:"Chợ Viềng",t:"l",d:8,m:1,g:"khac",p:"Chợ Viềng Phủ; Chợ Viềng Chùa",s:"Phiên chợ mỗi năm họp một lần, từ đêm mùng 7 tới rạng sáng mùng 8 tháng Giêng, theo tinh thần mua may bán rủi. Người ta mua nông cụ, cây giống, thịt bò lấy lộc đầu năm. Có hai chợ…",b:1},{id:"dai-le-hoi-yen-dieu-tri-cung",n:"Đại lễ Hội Yến Diêu Trì Cung",t:"l",d:15,m:8,j:1,g:"tin-nguong",p:"Tòa Thánh Tây Ninh",s:"Đại lễ lớn của đạo Cao Đài dâng Đức Phật Mẫu vào rằm tháng Tám, có tiệc chay từ năm 1925; năm 2026 dự kiến hơn 300.000 tín đồ và du khách, hơn 150 gian hoa trái của các họ đạo.",a:1,y:{2026:"2026-09-25"}},{id:"festival-bien-khanh-hoa",n:"Festival Biển Khánh Hòa",t:"a",g:"khac",p:"Quảng trường 2 tháng 4",s:"Lễ hội biển của tỉnh Khánh Hòa tổ chức tại Nha Trang, có sự tham gia của các bộ, ngành, nhiều tỉnh thành và đối tác quốc tế. Ba ngày chính có lễ khai mạc ở Quảng trường 2 tháng 4,…",y:{2026:"2026-07-17"}},{id:"festival-dan-ca-dan-vu-quoc-te",n:"Festival Dân ca, Dân vũ quốc tế",t:"a",j:1,g:"khac",p:"Quảng trường 7/5",s:'Lần đầu Điện Biên đăng cai, chủ đề "Kết nối văn hóa, lan tỏa hòa bình, vươn tầm hội nhập", quy tụ đoàn dân ca dân vũ trong nước và quốc tế dịp Quốc khánh.',y:{2026:"2026-08-28"}},{id:"festival-du-lich-cua-lo",n:"Festival Du lịch Cửa Lò",t:"a",g:"khac",p:"Quảng trường Bình Minh",s:"Sự kiện mở mùa du lịch biển của Nghệ An, do UBND tỉnh chủ trì tại bãi biển Cửa Lò. Sau đêm khai mạc là chuỗi hoạt động kéo dài trong năm như carnaval biển, giải thể thao bãi biển,…",y:{2026:"2026-04-25"}},{id:"festival-hoa-da-lat",n:"Festival Hoa Đà Lạt",t:"a",j:1,g:"khac",p:"Quảng trường Lâm Viên",s:'Chủ đề "Đà Lạt, bản giao hòa của sắc hoa và âm nhạc", tổ chức trên phạm vi toàn tỉnh Lâm Đồng, hoạt động trọng tâm cuối tháng 12, một số chương trình hưởng ứng kéo sang đầu tháng…',y:{2026:"2026-12-19"}},{id:"festival-quoc-te-cong-chieng-gia-lai",n:"Festival quốc tế Cồng chiêng Gia Lai",t:"a",j:1,g:"khac",p:"Quảng trường Đại Đoàn Kết; Làng Ia Gri (chân núi lửa Chư Đăng Ya)",s:"Sự kiện trọng điểm của Năm Du lịch quốc gia Gia Lai 2026, khoảng 45 đội cồng chiêng trong và ngoài nước, kỷ niệm 21 năm UNESCO ghi danh Không gian văn hóa Cồng chiêng Tây Nguyên;…",y:{2026:"2026-11-07"}},{id:"festival-thu-ha-noi",n:"Festival Thu Hà Nội",t:"a",g:"khac",p:"Công viên Thống Nhất",s:"Festival mùa thu của Hà Nội với biểu diễn nghệ thuật, không gian văn hóa và ẩm thực.",y:{2026:"2026-10-16"}},{id:"festival-tra-quoc-te-thai-nguyen",n:"Festival Trà quốc tế Thái Nguyên",t:"a",j:1,g:"khac",p:"Quảng trường Võ Nguyên Giáp",s:'Festival chủ đề "Thái Nguyên, Đệ nhất danh trà" với phố trà, diễn đàn trà quốc tế và cuộc thi Vietnam Master Tea, tôn vinh vùng chè Tân Cương và văn hóa trà.',y:{2026:"2026-10-30"}},{id:"gio-to-hung-vuong",n:"Giỗ Tổ Hùng Vương",t:"l",d:10,m:3,h:1,j:1,g:"le-tet",s:"Ngày giỗ tổ, tưởng nhớ các Vua Hùng có công dựng nước, quốc lễ của Việt Nam."},{id:"hoi-den-va",n:"Hội Thu đền Và",t:"l",d:15,m:9,g:"tin-nguong",p:"Đền Và",s:"Hội mùa Thu đền Và thờ Tản Viên Sơn Thánh, diễn ra 14 và 15 tháng Chín âm lịch, có lễ đả ngư (đánh cá dâng Thánh).",b:1},{id:"hoi-dua-bo-bay-nui",n:"Hội đua bò Bảy Núi",t:"a",g:"tin-nguong",p:"Sân đua bò xã An Cư, gần chùa Thơ Mít (giải ATV lần 31); Sân đua chùa Rô, ấp…",s:"Hội đua bò của người Khmer vùng Bảy Núi gắn với lễ Sene Dolta; giải truyền thống Chùa Rô năm 2026 đã diễn ra 13/9 với 32 đôi bò, giải ATV lần thứ 31 dự kiến ngày 10/10.",y:{2026:"2026-10-10"}},{id:"hoi-giong-den-phu-dong",n:"Hội Gióng đền Phù Đổng",t:"l",d:9,m:4,g:"tin-nguong",s:"Hội Gióng ở quê nhà Thánh Gióng, diễn ra 7 tới 9 tháng Tư âm lịch, chính hội ngày 9. Hội Gióng được UNESCO ghi danh Di sản văn hóa phi vật thể đại diện của nhân loại năm 2010.",b:2},{id:"hoi-giong-den-soc",n:"Hội Gióng đền Sóc",t:"l",d:6,m:1,j:1,g:"tin-nguong",s:"Hội Gióng đền Sóc được tổ chức từ ngày 6 đến 8 tháng Giêng tại xã Phù Linh, Sóc Sơn, tưởng nhớ Thánh Gióng, vị anh hùng đánh giặc Ân, nơi ngài hóa trước khi về trời. Lễ hội đã…"},{id:"hoi-hang-pinh",n:"Hội Háng Pỉnh",t:"l",d:12,m:8,g:"tin-nguong",p:"Chợ Kỳ Lừa; Tượng đài đồng chí Hoàng Văn Thụ",s:"Hội chợ bánh nướng dịp Trung thu của người Tày, Nùng xứ Lạng, theo lệ họp ngày 12 tháng 8 âm lịch ở chợ Kỳ Lừa, có hát sli, thưởng bánh và trò chơi dân gian.",y:{2026:"2026-09-22"}},{id:"hoi-lim",n:"Hội Lim",t:"l",d:13,m:1,j:1,g:"tin-nguong",s:"Hội Lim là lễ hội quan họ lớn nhất vùng Kinh Bắc, diễn ra chính vào ngày 13 tháng Giêng tại đồi Lim, huyện Tiên Du, gồm tế lễ và hát quan họ đối đáp giữa các liền anh, liền chị.",b:1,a:1},{id:"hoi-vat-lang-sinh",n:"Hội vật làng Sình",t:"l",d:10,m:1,g:"tin-nguong",p:"Đình làng Lại Ân (làng Sình)",s:"Hội vật làng Sình diễn ra trọn một ngày mùng 10 tháng Giêng ở đình làng Lại Ân, có từ thời chúa Nguyễn. Sau lễ tế Thành hoàng, bất kỳ khán giả nào cũng được đăng ký lên sới vật."},{id:"hoi-vat-vo-lieu-doi",n:"Hội vật võ Liễu Đôi",t:"l",d:5,m:1,g:"tin-nguong",p:"Làng Liễu Đôi",s:"Hội vật võ của làng Liễu Đôi, xã Liêm Túc, Thanh Liêm, Ninh Bình (Hà Nam cũ), mở ngày mùng 5 Tết, thờ Đức Thánh Tiên, tổ sư dòng họ Đoàn. Hội mở đầu bằng năm keo vật Trai Rốt do…"},{id:"hoi-xuan-chua-keo",n:"Hội Xuân chùa Keo",t:"l",d:4,m:1,g:"tin-nguong",p:"Chùa Keo (Thần Quang tự)",s:"Hội xuân ở chùa Keo mở từ mùng 4 tháng Giêng, với lễ khai chỉ, múa rối chầu Thánh và lễ tế ở Giá Roi. Phần hội có thi thổi cơm, bắt vịt dưới hồ, hát chèo thuyền, đánh trống bịt…",a:4},{id:"khai-hoi-chua-bai-dinh",n:"Khai hội chùa Bái Đính",t:"l",d:6,m:1,g:"tin-nguong",p:"Chùa Bái Đính",s:"Lễ khai hội chùa Bái Đính diễn ra mùng 6 tháng Giêng và mùa hội kéo dài tới hết tháng Ba âm lịch. Phần lễ tưởng nhớ Quốc sư Nguyễn Minh Không, tế thần Cao Sơn và chầu Mẫu Thượng…"},{id:"le-cac-thanh-tu-dao-viet-nam",n:"Lễ Các Thánh Tử đạo Việt Nam",t:"s",d:24,m:11,g:"tin-nguong",p:"Trung tâm hành hương Các Thánh Tử đạo Việt Nam, Sở Kiện",s:"Ngày 24 tháng 11 là lễ trọng kính 117 Thánh Tử đạo Việt Nam, được Giáo hoàng Gioan Phaolô II tôn phong hiển thánh năm 1988, và là lễ bổn mạng của Giáo hội Công giáo Việt Nam. Các…"},{id:"le-giang-sinh",n:"Lễ Giáng sinh",t:"s",d:25,m:12,j:1,g:"tin-nguong",p:"Nhà thờ Đức Bà Sài Gòn; Nhà thờ Lớn Hà Nội",s:"Lễ mừng Chúa Giáng sinh của người Công giáo: lễ vọng đêm 24/12 và lễ chính ngày 25/12. Ở Việt Nam, Noel còn là dịp chung của cả người không theo Công giáo, nhất là ở các thành phố…"},{id:"le-gio-anh-hung-dan-toc-truong-dinh",n:"Lễ giỗ Anh hùng dân tộc Trương Định",t:"s",d:20,m:8,g:"tin-nguong",p:"Đền thờ và lăng mộ Trương Định; Đình Gia Thuận",s:"Lễ giỗ Bình Tây Đại nguyên soái Trương Định, người lãnh đạo nghĩa quân Gò Công chống Pháp, tuẫn tiết ngày 20/8/1864. Lễ được giữ theo ngày dương lịch, có rước linh, dâng hoa tại…",y:{2026:"2026-08-18"}},{id:"le-gio-ba-phi-yen",n:"Lễ giỗ bà Phi Yến",t:"l",d:18,m:10,g:"tin-nguong",p:"An Sơn Miếu (Miếu Bà Phi Yến)",s:"Người dân Côn Đảo làm giỗ bà Phi Yến ngày 18 tháng Mười âm lịch tại An Sơn Miếu: từ đêm 17 đã bày cúng và đãi khách, lễ chính sáng 18 gồm tế lễ, dâng hương, rước bài vị. Theo…",b:1},{id:"le-gio-dai-thi-hao-nguyen-du",n:"Lễ giỗ Đại thi hào Nguyễn Du",t:"l",d:10,m:8,g:"tin-nguong",p:"Khu lưu niệm Đại thi hào Nguyễn Du",s:"Lễ giỗ lần thứ 206 tổ chức ngày 20/9/2026 (10/8 âm), dâng hương tại mộ và nhà thờ, do dòng họ Nguyễn Tiên Điền thực hiện nghi lễ.",y:{2026:"2026-09-20"}},{id:"le-gio-hoang-de-quang-trung",n:"Lễ giỗ Hoàng đế Quang Trung",t:"l",d:29,m:7,g:"tin-nguong",p:"Bảo tàng Quang Trung, đền thờ Tây Sơn Tam Kiệt",s:"Lễ giỗ lần thứ 234 của Hoàng đế Quang Trung Nguyễn Huệ tổ chức ngày 10/9/2026, tức 29 tháng Bảy âm, tại Bảo tàng Quang Trung.",y:{2026:"2026-09-10"}},{id:"le-gio-le-thanh-hau-nguyen-huu-canh",n:"Lễ giỗ Lễ Thành hầu Nguyễn Hữu Cảnh",t:"l",d:16,m:5,g:"tin-nguong",p:"Di tích Đền thờ và mộ Nguyễn Hữu Cảnh",s:"Lễ giỗ danh tướng Nguyễn Hữu Cảnh (1650 tới 1700), người được chúa Nguyễn Phúc Chu cử vào kinh lược phương Nam năm 1698, lập làng và dựng bộ máy hành chính cho vùng Đồng Nai, Gia…",b:1,y:{2026:"2026-06-30"}},{id:"le-gio-ta-quan-le-van-duyet",n:"Lễ giỗ Tả quân Lê Văn Duyệt",t:"l",d:1,m:8,g:"tin-nguong",p:"Lăng Ông Bà Chiểu (lăng Tả quân Lê Văn Duyệt)",s:"Lễ giỗ ở lăng Ông Bà Chiểu, nơi yên nghỉ của Tả quân Lê Văn Duyệt, hai lần làm Tổng trấn Gia Định. Lễ kéo dài ba ngày từ 30 tháng Bảy tới mùng 2 tháng Tám âm lịch, có dâng rượu…",b:1,a:1},{id:"le-gio-uy-vien-tuong-cong-nguyen-cong-tru",n:"Lễ giỗ Uy Viễn tướng công Nguyễn Công Trứ",t:"l",d:14,m:11,g:"tin-nguong",p:"Khu di tích nhà thờ Nguyễn Công Trứ, thôn Lam Thủy",s:"Nguyễn Công Trứ mất ngày 14 tháng Mười một năm Mậu Ngọ (1858) tại quê Uy Viễn; lễ giỗ tổ chức hằng năm vào ngày này tại nhà thờ ông."},{id:"le-ha-nguon-va-ky-niem-ngay-khai-dao-cao-dai",n:"Lễ Hạ Ngươn và kỷ niệm ngày Khai Đạo Cao Đài",t:"l",d:15,m:10,g:"tin-nguong",p:"Tòa Thánh Tây Ninh",s:"Rằm tháng Mười âm lịch, Hội Thánh Cao Đài Tòa Thánh Tây Ninh làm lễ Hạ Ngươn gắn với kỷ niệm ngày Khai Đạo: lễ khai minh Đại Đạo Tam Kỳ Phổ Độ diễn ra ngày 15 tháng 10 năm Bính…"},{id:"le-hoi-anh-sang-bien-cuong-lan-thu-nhat",n:"Lễ hội Ánh sáng biên cương lần thứ nhất",t:"a",g:"tin-nguong",p:"Sân khấu đường Hùng Vương",s:"Lễ hội đèn dịp Trung thu lần đầu tổ chức ở Lạng Sơn, có diễu hành 8 mô hình đèn lớn và 14 mô hình của các xã phường, trong đó có mô hình đàn tính của người Tày, Nùng.",y:{2026:"2026-09-19"}},{id:"le-hoi-ao-dai-thanh-pho-ho-chi-minh",n:"Lễ hội Áo dài Thành phố Hồ Chí Minh",t:"a",g:"khac",p:"Phố đi bộ Nguyễn Huệ và Công viên tượng đài Chủ tịch Hồ Chí Minh",s:"Lễ hội tôn vinh áo dài do Sở Du lịch và Hội Liên hiệp Phụ nữ TP.HCM tổ chức suốt tháng Ba, gắn với Ngày Quốc tế Phụ nữ. Có đêm khai mạc trên phố đi bộ Nguyễn Huệ, đồng diễn và…",y:{2026:"2026-03-01"}},{id:"le-hoi-ba-chua-kho",n:"Lễ hội Đền Bà Chúa Kho",t:"l",d:14,m:1,j:1,g:"tin-nguong",s:"Lễ hội Đền Bà Chúa Kho diễn ra vào ngày 14 tháng Giêng tại Cổ Mễ, TP Bắc Ninh, tưởng nhớ Bà Chúa Kho, người có công giữ kho lương cho quân đội thời Lý và hy sinh trên chiến tuyến…"},{id:"le-hoi-ba-thu-bon",n:"Lễ hội Bà Thu Bồn",t:"l",d:12,m:2,g:"tin-nguong",p:"Dinh Bà Thu Bồn",s:"Các làng ven sông Thu Bồn cùng mở hội từ 10 tới 12 tháng Hai, lớn nhất ở làng Thu Bồn nơi có Dinh Bà. Có lễ rước sắc, rước nước, đua thuyền, cầu mùa màng và quốc thái dân an. Di…",b:2},{id:"le-hoi-bach-dang",n:"Lễ hội Bạch Đằng",t:"l",d:8,m:3,g:"tin-nguong",p:"Khu di tích Bạch Đằng, đền Trần Hưng Đạo",s:"Lễ hội từ mùng 6 tới mùng 8 tháng Ba, ngày giỗ trận Bạch Đằng, tưởng nhớ các anh hùng trên sông Bạch Đằng năm 938 và 1288. Tế chính hội ở đền Trần Hưng Đạo, cùng lễ rước qua miếu…",b:2},{id:"le-hoi-cau-ngu-man-mua-o-van-thuy-tu",n:"Lễ hội Cầu ngư mãn mùa ở Vạn Thủy Tú",t:"l",d:23,m:8,g:"tin-nguong",p:"Dinh Vạn Thủy Tú",s:"Vạn Thủy Tú có ba kỳ cầu ngư mỗi năm: đầu mùa 20/4, chính mùa 19-22/6 và mãn mùa 23/8 âm lịch; dinh lưu giữ hơn 100 bộ xương cá Ông."},{id:"le-hoi-cho-tinh-khau-vai",n:"Lễ hội Chợ tình Khâu Vai",t:"l",d:27,m:3,j:1,g:"khac",p:"Chợ Khâu Vai",s:"Phiên chợ hình thành từ năm 1919, mỗi năm chỉ họp một lần vào ngày 27 tháng Ba âm lịch, gắn với truyện tình chàng Ba người Nùng và nàng Út người Giáy. Người vùng cao về đây gặp…",b:1,y:{2026:"2026-05-12"}},{id:"le-hoi-choi-trau-do-son",n:"Lễ hội Chọi trâu Đồ Sơn",t:"l",d:9,m:8,g:"tin-nguong",p:"Sân vận động trung tâm phường Đồ Sơn",s:"Lễ hội truyền thống của ngư dân vùng biển Đồ Sơn, chung kết diễn ra vào ngày 9 tháng 8 âm lịch với các trận đấu trâu, sau đó trâu thắng được dùng làm vật hiến tế cầu mùa; là Di…",y:{2026:"2026-09-19"}},{id:"le-hoi-choi-trau-hai-luu",n:"Lễ hội chọi trâu Hải Lựu",t:"l",d:16,m:1,g:"tin-nguong",p:"Xã Hải Lựu",s:"Lễ hội chọi trâu ở xã Hải Lựu, Phú Thọ (Vĩnh Phúc cũ), diễn ra ngày 16 và 17 tháng Giêng. Dân làng thờ Lữ Gia làm thành hoàng, và theo truyền thuyết địa phương, hội chọi trâu bắt…",a:1},{id:"le-hoi-chu-dong-tu-tien-dung",n:"Lễ hội Chử Đồng Tử, Tiên Dung",t:"l",d:10,m:2,g:"tin-nguong",s:"Lễ hội đền Đa Hòa, Dạ Trạch thờ Chử Đồng Tử và công chúa Tiên Dung, diễn ra 10 tới 12 tháng Hai âm lịch. Hội lớn đủ chín làng ba năm mới tổ chức một lần.",a:2},{id:"le-hoi-chua-ba-thien-hau-thu-dau-mot",n:"Lễ hội chùa Bà Thiên Hậu Thủ Dầu Một",t:"l",d:15,m:1,j:1,g:"tin-nguong",p:"Miếu Bà Thiên Hậu (chùa Bà Bình Dương)",s:"Lễ hội Rằm tháng Giêng ở miếu Bà Thiên Hậu do bốn bang Hoa lập hơn trăm năm trước là một trong những lễ hội tín ngưỡng lớn nhất Nam Bộ. Điểm nhấn là lễ rước kiệu Bà qua phố với…",b:1},{id:"le-hoi-chua-co-le",n:"Lễ hội chùa Cổ Lễ",t:"l",d:14,m:9,g:"tin-nguong",p:"Chùa Cổ Lễ (Thần Quang tự)",s:"Lễ hội ở chùa Cổ Lễ (Thần Quang tự) diễn ra từ 13 đến 16 tháng Chín âm lịch, chính hội ngày 14 là ngày hóa của Đức Thánh Tổ Nguyễn Minh Không, vị thiền sư được thờ tại chùa. Phần…",b:1,a:2},{id:"le-hoi-chua-dau",n:"Lễ hội chùa Dâu",t:"l",d:8,m:4,g:"tin-nguong",p:"Chùa Dâu (Diên Ứng tự)",s:"Hội chùa Dâu mùng 8 tháng Tư do 12 làng của hương Dâu, Luy Lâu cũ tổ chức ở ngôi chùa được xem là cổ nhất Việt Nam. Linh hồn của hội là rước Phật Tứ Pháp từ các chùa làng về chùa…"},{id:"le-hoi-chua-huong",n:"Lễ hội Chùa Hương",t:"l",d:6,m:1,j:1,g:"tin-nguong",s:"Lễ hội Chùa Hương là lễ hội hành hương lớn nhất miền Bắc, khai hội vào ngày mùng 6 tháng Giêng tại sân chùa Thiên Trù và kéo dài đến hết tháng 3 âm lịch."},{id:"le-hoi-chua-keo-hanh-thien",n:"Lễ hội chùa Keo Hành Thiện",t:"l",d:10,m:9,g:"tin-nguong",p:"Chùa Keo Hành Thiện (Thần Quang tự)",s:"Hội thờ Thiền sư Dương Không Lộ, có bơi chải đứng ngày 12 và 15 tháng 9 âm lịch cùng các trò đếm tôm, bắt vịt, cờ người; khác với hội chùa Keo ở Thái Bình cũ.",a:6},{id:"le-hoi-chua-keo-mua-thu",n:"Lễ hội chùa Keo mùa Thu",t:"l",d:15,m:9,g:"tin-nguong",p:"Chùa Keo (Thần Quang tự)",s:"Hội mùa Thu chùa Keo tưởng niệm Thiền sư Dương Không Lộ, diễn ra 10 tới 15 tháng Chín âm lịch với rước kiệu và thi bơi chải trên sông.",b:5,y:{2026:"2026-10-24"}},{id:"le-hoi-chua-ong-cu-lao-pho",n:"Lễ hội chùa Ông cù lao Phố",t:"l",d:10,m:1,g:"tin-nguong",p:"Chùa Ông (Thất Phủ cổ miếu)",s:"Lễ hội tại Thất Phủ cổ miếu, ngôi chùa thờ Quan Thánh Đế Quân dựng năm 1684 bên sông Đồng Nai. Điểm nhấn là lễ Nghinh thần quanh chợ Biên Hòa, cùng đờn ca tài tử, lân sư rồng, thư…",a:3},{id:"le-hoi-chua-thay",n:"Lễ hội chùa Thầy",t:"l",d:7,m:3,g:"tin-nguong",p:"Chùa Thầy (Thiên Phúc tự)",s:"Lễ hội tiêu biểu của xứ Đoài, tưởng nhớ thiền sư Từ Đạo Hạnh thời Lý, người được xem là ông tổ múa rối nước. Chính hội mùng 5 tới mùng 7 tháng Ba, có múa rối nước ở thủy đình và…",b:2},{id:"le-hoi-co-loa",n:"Lễ hội Cổ Loa",t:"l",d:6,m:1,g:"tin-nguong",s:"Lễ hội Cổ Loa được tổ chức vào ngày mùng 6 tháng Giêng tại khu di tích Cổ Loa, tưởng nhớ vua An Dương Vương, người lập nên nhà nước Âu Lạc và xây thành Cổ Loa."},{id:"le-hoi-com-moi-den-dong-cuong",n:"Lễ hội Cơm mới đền Đông Cuông",t:"a",g:"tin-nguong",p:"Đền Đông Cuông",s:"Lễ của người Tày Khao ở xã Đông Cuông, tổ chức tại đền Đông Cuông (di tích lịch sử quốc gia) sau vụ mùa để dâng cơm mới tạ ơn thần linh. Theo phong tục, lễ vào ngày Mão của tháng…",y:{2025:"2025-10-24",2026:"2026-10-20"}},{id:"le-hoi-con-son-kiep-bac-mua-thu",n:"Lễ hội Côn Sơn, Kiếp Bạc mùa Thu",t:"l",d:20,m:8,j:1,g:"tin-nguong",p:"Khu di tích Côn Sơn; Đền Kiếp Bạc",s:"Mùa hội Thu của khu di tích Côn Sơn, Kiếp Bạc, lấy ngày giỗ Đức Thánh Trần Hưng Đạo 20 tháng Tám âm lịch làm chính hội. Khu di tích thuộc quần thể Yên Tử, Vĩnh Nghiêm, Côn Sơn,…",y:{2026:"2026-09-30"}},{id:"le-hoi-con-son-kiep-bac-mua-xuan",n:"Lễ hội Côn Sơn, Kiếp Bạc mùa Xuân",t:"l",d:18,m:1,g:"tin-nguong",p:"Khu di tích Côn Sơn, Kiếp Bạc",s:"Hội mùa xuân ở khu di tích Côn Sơn, Kiếp Bạc gồm lễ tế ở đền Nguyễn Trãi, đền thờ Trần Nguyên Đán và lễ giỗ Đệ Tam Tổ Trúc Lâm Huyền Quang ngày 18 tháng Giêng. Khác hội mùa thu…",b:8,a:5},{id:"le-hoi-cung-bien-my-long",n:"Lễ hội Cúng biển Mỹ Long",t:"l",d:10,m:5,g:"tin-nguong",p:"Lăng Ông và bãi biển Mỹ Long",s:"Lễ hội của ngư dân Mỹ Long cúng thần Nam Hải, cầu quốc thái dân an, mưa thuận gió hòa và mùa cá bội thu, tổ chức ngày 10 tới 12 tháng Năm âm lịch. Lễ cúng Thần Biển làm trang…",a:2,y:{2026:"2026-06-20"}},{id:"le-hoi-den-an-xa",n:"Lễ hội đền An Xá",t:"l",d:6,m:4,g:"tin-nguong",p:"Đền An Xá (đền Đậu An)",s:"Lễ hội ở đền An Xá, tức đền Đậu An, thờ Ngọc Hoàng Thượng Đế, Ngũ Lão Tiên Ông cùng các vị tiên có công lập làng. Hội mở từ mùng 1 tới 12 tháng Tư âm lịch, chính hội ngày 6 tới 8.…",b:5,a:6,y:{2026:"2026-05-22"}},{id:"le-hoi-den-ba-trieu",n:"Lễ hội đền Bà Triệu",t:"l",d:22,m:2,g:"tin-nguong",s:"Lễ hội tưởng nhớ nữ anh hùng Triệu Thị Trinh, chính hội ngày 22 tháng Hai âm lịch là ngày giỗ Bà. Các nguồn ghi khoảng ngày hội khác nhau giữa các năm, thường 21 tới 23 tháng Hai.",b:1,a:1},{id:"le-hoi-den-bao-ha",n:"Lễ hội đền Bảo Hà",t:"l",d:17,m:7,g:"tin-nguong",p:"Đền Bảo Hà (đền Ông Hoàng Bảy)",s:"Lễ hội ngày 17 tháng Bảy âm lịch tưởng nhớ danh tướng Hoàng Bảy, người đánh giặc giữ vùng biên cuối thời Hậu Lê, được triều Nguyễn phong Thần vệ quốc. Dân gian quen gọi là đền Ông…"},{id:"le-hoi-den-cho-cui",n:"Lễ hội đền Chợ Củi",t:"l",d:3,m:10,g:"tin-nguong",p:"Đền Chợ Củi",s:"Lễ hội ở đền thờ Quan Hoàng Mười bên bờ sông Lam, theo lệ diễn ra từ mùng 3 đến mùng 10 tháng Mười âm, chính giỗ ngày 10; năm 2025 tổ chức 22-29/11 dương lịch.",a:7},{id:"le-hoi-den-con",n:"Lễ hội đền Cờn",t:"l",d:20,m:1,g:"tin-nguong",p:"Đền Cờn",s:"Lễ hội lớn bậc nhất xứ Nghệ, mang đậm văn hóa biển, ở ngôi đền bên sông Mai Giang. Có lễ rước kiệu, chạy ói, cầu ngư, đại tế, cùng đua thuyền, cờ thẻ, kéo co. Di sản văn hóa phi…",b:1,a:1},{id:"le-hoi-den-cong-dong-bac-le",n:"Lễ hội đền Công Đồng Bắc Lệ",t:"l",d:18,m:9,g:"tin-nguong",p:"Đền Công Đồng Bắc Lệ",s:"Lễ hội ở ngôi đền thờ Mẫu Thượng Ngàn nổi tiếng xứ Lạng, diễn ra 18 đến 20 tháng 9 âm lịch với lễ tắm ngai, lễ chính tiệc Mẫu và lễ rước.",a:2},{id:"le-hoi-den-cua-ong",n:"Lễ hội đền Cửa Ông",t:"l",d:3,m:2,g:"tin-nguong",p:"Đền Cửa Ông",s:"Lễ hội tưởng nhớ Hưng Nhượng Vương Trần Quốc Tảng, con trai Hưng Đạo Đại vương, người trấn giữ vùng biên Đông Bắc. Đền gồm đền Hạ, đền Trung, đền Thượng trên sườn đồi nhìn ra vịnh…",a:1},{id:"le-hoi-den-cuong",n:"Lễ hội đền Cuông",t:"l",d:15,m:2,g:"tin-nguong",p:"Đền Cuông",s:"Lễ hội ở đền Cuông trên núi Mộ Dạ tưởng nhớ Thục An Dương Vương. Sáng 15 tháng Hai rước kiệu Vua, kiệu công chúa Mỵ Châu và kiệu tướng Cao Lỗ từ nhà thờ họ Cao và đền Xuân Ái về…",b:3,a:1},{id:"le-hoi-den-do",n:"Lễ hội đền Đô",t:"l",d:15,m:3,g:"tin-nguong",s:"Lễ hội đền thờ tám vị vua triều Lý, diễn ra 14 tới 16 tháng Ba âm lịch, chính hội ngày 15 kỷ niệm Lý Công Uẩn lên ngôi.",b:1,a:1},{id:"le-hoi-den-dong-bang",n:"Lễ hội đền Đồng Bằng",t:"l",d:20,m:8,g:"tin-nguong",p:"Đền Đồng Bằng",s:"Hội tứ phủ lớn ở đền Đồng Bằng, thờ Vua Cha Bát Hải Động Đình cùng Hưng Đạo Đại Vương và các tướng nhà Trần, mở ngày 20 tới 26 tháng Tám âm lịch. Có rước kiệu, hát văn hầu đồng,…",a:6},{id:"le-hoi-den-hai-ba-trung-me-linh",n:"Lễ hội đền Hai Bà Trưng (Mê Linh)",t:"l",d:6,m:1,g:"tin-nguong",s:"Lễ hội tưởng nhớ Hai Bà Trưng tại quê nhà Mê Linh, khai hội mùng 6 tháng Giêng và kéo dài tới mùng 8.",a:2},{id:"le-hoi-den-hat-mon",n:"Lễ hội đền Hát Môn",t:"l",d:6,m:3,g:"tin-nguong",p:"Đền Hát Môn",s:"Mùng 6 tháng Ba là ngày Hai Bà Trưng hóa ở sông Hát, dân Hát Môn mở hội từ mùng 4 tới mùng 6. Nét riêng là tục rước bánh trôi dâng Hai Bà, theo tích Hai Bà ăn bánh trôi trước khi…",b:2},{id:"le-hoi-den-ky-cung-den-ta-phu",n:"Lễ hội đền Kỳ Cùng, đền Tả Phủ",t:"l",d:22,m:1,g:"tin-nguong",p:"Đền Kỳ Cùng; Đền Tả Phủ",s:"Lễ hội lớn nhất xứ Lạng, diễn ra từ 22 tới 27 tháng Giêng. Ngày 22 rước kiệu Quan Tuần Tranh từ đền Kỳ Cùng sang đền Tả Phủ tạ ơn Hán Quận Công Thân Công Tài, ngày 27 rước về. Di…",a:5},{id:"le-hoi-den-mau-au-co",n:"Lễ hội đền Mẫu Âu Cơ",t:"l",d:7,m:1,g:"tin-nguong",p:"Đền Mẫu Âu Cơ",s:"Mùng 7 tháng Giêng là ngày tương truyền Tổ Mẫu Âu Cơ giáng trần, dân Hiền Lương mở hội dâng hương tri ân người mẹ của trăm trứng. Tín ngưỡng thờ Mẫu Âu Cơ là Di sản văn hóa phi…"},{id:"le-hoi-den-ong-hoang-muoi",n:"Lễ hội đền Ông Hoàng Mười",t:"l",d:10,m:10,g:"tin-nguong",p:"Đền Ông Hoàng Mười, làng Xuân Am",s:"Ngày 10 tháng Mười âm là ngày hóa của Quan Hoàng Mười; lễ gồm rước sắc phong, yết cáo, đại tế, nghi lễ hầu đồng và các trò chơi dân gian."},{id:"le-hoi-den-tho-le-lai",n:"Lễ hội đền thờ Lê Lai",t:"l",d:21,m:8,g:"tin-nguong",p:"Đền thờ Trung Túc Vương Lê Lai (đền Tép), làng Tép",s:'Lễ hội diễn ra ngày 21 tháng Tám âm (ngày trước lễ Lam Kinh 22/8, theo câu "hai mốt Lê Lai, hai hai Lê Lợi") và mùng 8 tháng Giêng, có tế lễ, rước kiệu, hát chầu văn, múa kiếm.'},{id:"le-hoi-den-thuong-lao-cai",n:"Lễ hội đền Thượng Lào Cai",t:"l",d:15,m:1,g:"tin-nguong",p:"Đền Thượng",s:"Lễ hội Rằm tháng Giêng ở đền Thượng nơi cửa khẩu Lào Cai tưởng nhớ Hưng Đạo Đại vương Trần Quốc Tuấn. Có lễ rước kiệu lên đền và dâng hương cầu quốc thái dân an. Di sản văn hóa…"},{id:"le-hoi-den-tran-thai-binh",n:"Lễ hội đền Trần Thái Bình",t:"l",d:13,m:1,g:"tin-nguong",p:"Khu lăng mộ và đền thờ các vua triều Trần",s:"Lễ hội ở khu lăng mộ và đền thờ các vua triều Trần tại Tiến Đức, quê gốc nhà Trần, tưởng nhớ các vua Trần. Có lễ bái yết, rước nước, khai ấn. Di sản văn hóa phi vật thể quốc gia…",a:4},{id:"le-hoi-den-trang-trinh-nguyen-binh-khiem",n:"Lễ hội đền Trạng Trình Nguyễn Bỉnh Khiêm",t:"l",d:28,m:11,g:"tin-nguong",p:"Khu di tích đền thờ Trạng Trình Nguyễn Bỉnh Khiêm",s:"Lễ hội ở khu di tích đền thờ Trạng Trình Nguyễn Bỉnh Khiêm (1491-1585) tại Vĩnh Bảo, Hải Phòng, dịp ngày mất của ông 28 tháng 11 âm lịch. Có đoàn rước, dâng hương, đọc chúc văn…",b:1,a:1},{id:"le-hoi-den-tranh",n:"Lễ hội đền Tranh",t:"l",d:25,m:5,g:"tin-nguong",p:"Đền Tranh",s:"Lễ hội ở đền Tranh thờ Quan Lớn Tuần Tranh, một vị quan trong tín ngưỡng thờ Mẫu Tam phủ. Cả tháng Năm âm lịch là tháng tiệc với hát chầu văn, chính tiệc ngày 25 là ngày mất tương…"},{id:"le-hoi-dien-hue-nam",n:"Lễ hội điện Huệ Nam",t:"l",d:2,m:3,g:"tin-nguong",p:"Điện Huệ Nam (điện Hòn Chén)",s:"Lễ hội thờ Thánh Mẫu Thiên Y A Na ở điện Hòn Chén trên núi Ngọc Trản bên sông Hương, mở hai kỳ: xuân kỳ tháng Ba và thu tế tháng Bảy âm lịch. Có lễ cung nghinh Mẫu, rước thuyền…",a:1},{id:"le-hoi-dinh-cau",n:"Lễ hội Dinh Cậu",t:"l",d:15,m:10,g:"tin-nguong",p:"Dinh Cậu, cửa sông Dương Đông",s:"Lễ thờ Chúa Ngọc Nương Nương, Cậu Tài, Cậu Quý, gồm lễ Nghinh Cậu, Yết Cậu và Chánh tế đêm rằm tháng 10, cầu cho ngư dân đảo Phú Quốc đi biển bình an.",a:1},{id:"le-hoi-dinh-chem",n:"Lễ hội đình Chèm",t:"l",d:15,m:5,g:"tin-nguong",p:"Đình Chèm",s:"Hội làng Chèm giữa tháng Năm âm lịch tưởng nhớ Đức Thánh Chèm Lý Ông Trọng và phu nhân Bạch Tĩnh Cung. Nghi lễ đặc sắc nhất là rước nước bằng thuyền rồng ra giữa sông Hồng, cùng…",b:1,a:1},{id:"le-hoi-dinh-co-long-hai",n:"Lễ hội Dinh Cô Long Hải",t:"l",d:10,m:2,g:"tin-nguong",s:"Lễ hội của ngư dân vùng biển Long Hải tưởng nhớ Bà Cô, diễn ra 10 tới 12 tháng Hai âm lịch.",a:2},{id:"le-hoi-dinh-than-nguyen-trung-truc-rach-gia",n:"Lễ hội đình thần Nguyễn Trung Trực (Rạch Giá)",t:"l",d:26,m:8,g:"tin-nguong",p:"Đình thần Nguyễn Trung Trực, 8 Nguyễn Công Trứ; Công viên tượng đài Nguyễn…",s:"Lễ tưởng niệm Nguyễn Trung Trực bị thực dân Pháp xử chém năm 1868 tại Rạch Giá, hằng năm thu hút khoảng một triệu lượt khách; năm 2026 kỷ niệm 158 năm.",a:2,y:{2026:"2026-10-06"}},{id:"le-hoi-dinh-thay-thim",n:"Lễ hội Dinh Thầy Thím",t:"l",d:14,m:9,g:"tin-nguong",p:"Dinh Thầy Thím (rừng Bàu Cái) và mộ Thầy Thím (rừng Bàu Thông)",s:"Lễ giỗ chính của Dinh Thầy Thím kéo dài ba ngày với các nghi thức Nghinh Thần, Nhập điện an vị, Dâng cộ bánh, Chánh tế; ngoài ra còn lễ Tảo mộ mùng 5 tháng Giêng.",a:2},{id:"le-hoi-dinh-tra-co",n:"Lễ hội đình Trà Cổ",t:"l",d:1,m:6,g:"tin-nguong",p:"Đình Trà Cổ",s:"Lễ hội ở ngôi đình cổ nơi địa đầu Móng Cái, dựng từ năm 1461, diễn ra từ 30 tháng Năm tới mùng 3 tháng Sáu âm lịch. Nét riêng là lễ rước Ông Voi chầu thần. Di sản văn hóa phi vật…",b:1,a:2},{id:"le-hoi-dong-da-tay-son",n:"Lễ hội Đống Đa, Tây Sơn",t:"l",d:5,m:1,j:1,g:"tin-nguong",p:"Bảo tàng Quang Trung",s:"Người đất Tây Sơn mừng chiến thắng Ngọc Hồi, Đống Đa tại Bảo tàng Quang Trung, quê hương ba anh em nhà Tây Sơn, vào chiều mùng 4 và ngày mùng 5 Tết. Có võ cổ truyền Bình Định,…",b:1},{id:"le-hoi-du-lich-bien-sam-son",n:"Lễ hội Du lịch biển Sầm Sơn",t:"a",g:"khac",p:"Quảng trường biển Sầm Sơn",s:"Lễ khai hội mùa du lịch biển của Thanh Hóa, do tỉnh phối hợp với doanh nghiệp tổ chức ở quảng trường biển Sầm Sơn cuối tháng Tư. Chương trình nghệ thuật khai mạc kể lại hành trình…",y:{2026:"2026-04-25"}},{id:"le-hoi-dua-boi-thuyen-truyen-thong-tren-song-kien-giang",n:"Lễ hội đua, bơi thuyền truyền thống trên sông Kiến Giang",t:"s",d:2,m:9,g:"tin-nguong",p:"Sông Kiến Giang",s:"Hội đua thuyền mừng Tết Độc lập 2/9 trên quê hương Đại tướng Võ Nguyên Giáp; năm 2026 có hơn 1.000 vận động viên, lần đầu do xã Lệ Thủy chủ trì.",y:{2026:"2026-09-02"}},{id:"le-hoi-go-dong-da",n:"Lễ hội Gò Đống Đa",t:"l",d:5,m:1,j:1,g:"tin-nguong",p:"Di tích quốc gia đặc biệt Gò Đống Đa",s:"Lễ hội kỷ niệm chiến thắng Ngọc Hồi, Đống Đa, tưởng nhớ Hoàng đế Quang Trung và quân Tây Sơn đại phá quân Thanh mùa xuân Kỷ Dậu 1789. Có tế lễ, rước, dâng hương, biểu diễn võ…",a:1},{id:"le-hoi-gom-cham-bau-truc",n:"Lễ hội Gốm Chăm Bàu Trúc",t:"a",g:"tin-nguong",p:"Làng gốm Bàu Trúc",s:"Lễ hội lần đầu tổ chức, quy mô cấp xã mở rộng, gắn với Lễ hội Katê 2026, tôn vinh nghệ thuật làm gốm của người Chăm ở làng Bàu Trúc.",y:{2026:"2026-10-10"}},{id:"le-hoi-hoa-ban",n:"Lễ hội Hoa Ban",t:"a",g:"khac",p:"Sân vận động tỉnh Điện Biên",s:"Lễ hội mùa hoa ban của tỉnh Điện Biên, nằm trong Tuần Văn hóa - Du lịch Điện Biên vào tháng Ba dương lịch. Có carnaval đường phố, liên hoan dân ca, dân vũ, trình diễn thực cảnh và…",y:{2026:"2026-03-06"}},{id:"le-hoi-hoa-dao-xu-lang",n:"Lễ hội Hoa Đào xứ Lạng",t:"a",g:"khac",p:"Sân khấu đường Hùng Vương",s:"Lễ hội mùa đào của Lạng Sơn, gồm con đường hoa xuân, triển lãm hoa đào, giao lưu văn hóa, nghệ thuật và thể thao trong dịp Tết. Đêm khai mạc có bắn pháo hoa tầm cao ở khu vực cầu…",y:{2026:"2026-01-01"}},{id:"le-hoi-hoa-phuong-do",n:"Lễ hội Hoa Phượng Đỏ",t:"a",g:"khac",p:"Quảng trường Trung tâm Chính trị - Hành chính thành phố",s:"Lễ hội của thành phố Hải Phòng vào mùa hoa phượng, gắn với kỷ niệm Ngày Giải phóng Hải Phòng 13/5/1955, khởi nguồn từ năm 2012. Có chương trình nghệ thuật, bắn pháo hoa và nhiều…",y:{2026:"2026-05-08"}},{id:"le-hoi-hoa-tam-giac-mach",n:"Lễ hội hoa Tam giác mạch",t:"a",g:"khac",p:"Quảng trường Thanh niên",s:'Lễ hội lần thứ XII, chủ đề "Âm vang miền đá", tổ chức giữa mùa hoa tam giác mạch trên cao nguyên đá Đồng Văn. Kèm hội chợ thương mại quốc tế Việt Trung 5 đến 11/11 và không gian…',y:{2026:"2026-11-06"}},{id:"le-hoi-kate",n:"Lễ hội Katê",t:"a",g:"tin-nguong",p:"Tháp Pô Klong Garai; Tháp Pô Rômê; Tháp Pô Sah Inư; Đền thờ Pô Nit; Trung tâm…",s:"Katê là lễ hội lớn nhất năm của người Chăm Bàlamôn, tổ chức đầu tháng Bảy theo lịch Chăm để tưởng nhớ tổ tiên, thần linh và các vị vua Chăm. Lịch Chăm khác âm lịch Việt nên ngày…",y:{2025:"2025-10-21",2026:"2026-10-10"}},{id:"le-hoi-ky-yen-thoai-ngoc-hau",n:"Lễ hội Kỳ Yên đình Thoại Ngọc Hầu",t:"l",d:10,m:3,g:"tin-nguong",s:"Lễ hội cầu an tưởng nhớ Thoại Ngọc Hầu, người khai phá vùng Thoại Sơn, diễn ra 10 tới 12 tháng Ba âm lịch.",a:2},{id:"le-hoi-lam-chay",n:"Lễ hội Làm Chay",t:"l",d:16,m:1,g:"tin-nguong",p:"Đình Tân Xuân",s:"Lễ hội ở đình Tân Xuân, Tầm Vu, bắt nguồn từ việc dân làng mượn lễ trừ tà đuổi sâu bệnh để cúng hai nghĩa sĩ Đỗ Tường Tự, Đỗ Tường Phong bị thực dân Pháp xử tử và cấm tang. Có…",b:2},{id:"le-hoi-lam-kinh",n:"Lễ hội Lam Kinh",t:"l",d:22,m:8,g:"tin-nguong",p:"Khu di tích quốc gia đặc biệt Lam Kinh",s:"Lễ hội tưởng niệm vua Lê Thái Tổ (Lê Lợi) và các công thần khởi nghĩa Lam Sơn, diễn ra 21 tới 23 tháng Tám âm lịch, chính lễ ngày 22 là ngày giỗ vua.",b:1,a:1,y:{2026:"2026-10-02"}},{id:"le-hoi-lang-keo-gia-lam",n:"Lễ hội làng Keo Gia Lâm",t:"l",d:6,m:4,g:"tin-nguong",p:"Làng Keo",s:"Lễ hội làng Keo ở ngoại thành Hà Nội thờ hai vị Thành hoàng là tướng quân Đào Phúc và công chúa Tiên Anh, diễn ra từ mùng 6 tới mùng 8 tháng Tư âm lịch. Nghi thức riêng là thắng…",a:2,y:{2026:"2026-05-22"}},{id:"le-hoi-lang-sen",n:"Lễ hội Làng Sen",t:"a",g:"khac",p:"Khu di tích quốc gia đặc biệt Kim Liên",s:"Lễ hội của tỉnh Nghệ An tại quê nội Chủ tịch Hồ Chí Minh, tổ chức dịp kỷ niệm ngày sinh của Người 19/5. Có lễ dâng hoa, dâng hương, rước ảnh Bác, triển lãm và chương trình nghệ…",y:{2026:"2026-05-18"}},{id:"le-hoi-long-tong-ba-be",n:"Lễ hội Lồng Tồng Ba Bể",t:"l",d:10,m:1,g:"tin-nguong",p:"Bản Bó Lù, hồ Ba Bể",s:"Lễ hội xuống đồng của người Tày quanh hồ Ba Bể, cầu mưa thuận gió hòa, mùa màng tươi tốt. Hằng năm tổ chức mùng 10 tháng Giêng ở bản Bó Lù, xã Nam Mẫu, là Di sản văn hóa phi vật…"},{id:"le-hoi-ma-ma-me-cua-nguoi-kho-mu-nam-hang",n:"Lễ hội Mạ mạ mê của người Khơ Mú Nậm Hàng",t:"a",g:"tin-nguong",p:"Bản Nậm Manh, xã Nậm Hàng",s:"Lễ hội mừng lúa mới của người Khơ Mú ở bản Nậm Manh, xã Nậm Hàng, tạ ơn tổ tiên, ông bà và thần linh sau mùa gặt. Theo phong tục, lễ vào khoảng tháng Chín âm lịch, mỗi năm chọn…",y:{2025:"2025-10-25"}},{id:"le-hoi-mua-thu-y-ty-y-ty-suc-hut-dai-ngan",n:'Lễ hội mùa Thu Y Tý "Y Tý - Sức hút đại ngàn"',t:"a",g:"tin-nguong",p:"Chợ Y Tý",s:'Lễ hội mùa Thu đầu tiên do xã Y Tý tổ chức, chuỗi hoạt động từ 22/8 đến 15/11/2026: trải nghiệm hái và chế biến chè, trình diễn trang phục dân tộc, chạy "Mùa vàng Y Tý", chinh…',y:{2026:"2026-09-12"}},{id:"le-hoi-mua-vang-mu-cang-chai",n:"Lễ hội Mùa vàng Mù Cang Chải",t:"a",g:"tin-nguong",p:"Sân trung tâm xã Mù Cang Chải",s:'Lễ hội chủ đề "Sắc vàng non cao, khát vọng phát triển" trên danh thắng ruộng bậc thang Mù Cang Chải, với thi múa khèn Mông, vẽ sáp ong, giã bánh giầy và giải chạy Mù Cang Chải…',y:{2026:"2026-08-30"}},{id:"le-hoi-nghinh-ong-can-gio",n:"Lễ hội Nghinh Ông Cần Giờ",t:"l",d:16,m:8,g:"tin-nguong",p:"Lăng Ông Thủy Tướng; Công viên Cần Thạnh",s:"Lễ hội truyền thống của ngư dân Cần Giờ, tổ chức từ 14-16 tháng 8 âm lịch (chính lễ 16/8) để cúng tế cá Ông (thần Nam Hải) và cầu mưa thuận gió hòa, được công nhận Di sản văn hóa…",y:{2026:"2026-09-24"}},{id:"le-hoi-nghinh-ong-lai-son",n:"Lễ hội Nghinh Ông Lại Sơn",t:"l",d:15,m:10,g:"tin-nguong",p:"Lăng Ông Nam Hải Lại Sơn, đảo Hòn Sơn",s:"Lễ nghinh thần Nam Hải của ngư dân Kiên Hải, duy trì từ những năm 1990 trên nền tục thờ cá Ông hơn trăm năm; năm 2025 rơi vào 4 và 5/12.",a:1},{id:"le-hoi-nghinh-ong-nam-hai-binh-dai",n:"Lễ hội Nghinh Ông Nam Hải Bình Đại",t:"l",d:15,m:6,g:"tin-nguong",p:"Lăng Ông Nam Hải",s:"Lễ hội của ngư dân Bình Đại tạ ơn Ông Nam Hải, vị thần hộ mệnh người đi biển, tổ chức ngày 15 tới 17 tháng Sáu âm lịch. Lễ diễn ra ở Lăng Ông Nam Hải, phố chợ Bình Đại và cảng cá…",a:2,y:{2026:"2026-07-26"}},{id:"le-hoi-nghinh-ong-quan-thanh-de-quan-phan-thiet",n:"Lễ hội Nghinh Ông Quan Thánh Đế Quân Phan Thiết",t:"a",g:"tin-nguong",p:"Quan Đế Miếu (Chùa Ông) và bốn hội quán Quảng Đông, Phúc Kiến, Triều Châu, Hải…",s:"Lễ hội của cộng đồng người Hoa Phan Thiết, hai năm một lần vào các năm chẵn; lần thứ 15 năm 2026 có hơn 1.500 người tham gia đoàn rước.",y:{2026:"2026-09-06"}},{id:"le-hoi-nghinh-ong-song-doc",n:"Lễ hội Nghinh Ông Sông Đốc",t:"l",d:15,m:2,g:"tin-nguong",s:"Lễ hội biển lớn nhất Cà Mau, ngư dân rước Ông Nam Hải (cá voi) vào rằm tháng Hai âm lịch để cầu biển lặng, được mùa cá.",b:1},{id:"le-hoi-nghinh-ong-thang-tam",n:"Lễ hội Nghinh Ông Thắng Tam",t:"l",d:16,m:8,g:"tin-nguong",p:"Đình thần Thắng Tam và Lăng Cá Ông; Bãi Trước và đền Hòn Bà",s:"Lễ nghinh thần Nam Hải của ngư dân Vũng Tàu; năm 2026 thành phố gộp chung không gian với lễ hội Nghinh Ông Cần Giờ, lễ nghinh trên biển diễn ra ngày 26/9 rồi rước Ông về lăng.",a:2,y:{2026:"2026-09-26"}},{id:"le-hoi-nhay-lua-cua-nguoi-pa-then",n:"Lễ hội nhảy lửa của người Pà Thẻn",t:"l",d:16,m:10,g:"tin-nguong",p:"Thôn My Bắc",s:"Nghi lễ do thầy cúng chủ trì ngày 16 tháng 10 âm lịch, kết thúc mùa thu hoạch, trai làng lên đồng rồi nhảy chân trần vào đống than hồng để cầu bản làng no ấm. Người Pà Thẻn ở Lâm…"},{id:"le-hoi-nu-tuong-le-chan",n:"Lễ hội Nữ tướng Lê Chân",t:"l",d:8,m:2,g:"tin-nguong",s:"Lễ hội tưởng nhớ nữ tướng Lê Chân, người lập trang An Biên, tiền thân của Hải Phòng, diễn ra 7 tới 9 tháng Hai âm lịch.",b:1,a:1},{id:"le-hoi-ok-om-bok",n:"Lễ hội Ok Om Bok",t:"a",g:"tin-nguong",p:"Công viên 30/4 (khai mạc); Khán đài đua ghe Ngo trên sông Maspero; Khu di tích…",s:"Lễ hội tín ngưỡng lớn của người Khmer Nam Bộ, cúng trăng để tạ ơn thần Mặt Trăng, cầu mưa thuận gió hòa, thường đi kèm hội đua ghe Ngo; là Di sản văn hóa phi vật thể quốc gia. Lễ…",y:{2026:"2026-11-24"}},{id:"le-hoi-phao-hoa-quoc-te-da-nang",n:"Lễ hội Pháo hoa quốc tế Đà Nẵng",t:"a",j:1,g:"khac",p:"Bờ sông Hàn",s:"Cuộc thi trình diễn pháo hoa giữa các đội trong nước và quốc tế trên sông Hàn, diễn ra qua nhiều đêm thi và một đêm chung kết suốt mùa hè. Đi kèm là hàng chục hoạt động văn hóa,…",y:{2026:"2026-05-30"}},{id:"le-hoi-phet-hien-quan",n:"Lễ hội Phết Hiền Quan",t:"l",d:13,m:1,g:"tin-nguong",p:"Đình Hiền Quan",s:"Lễ hội ở Hiền Quan, Tam Nông, tưởng nhớ Thiều Hoa công chúa, nữ tướng thời Hai Bà Trưng, và Mộc Trang Đại vương thời Đinh. Hội diễn ra 12 và 13 tháng Giêng, chính hội ngày 13. Tục…",b:1},{id:"le-hoi-phu-day",n:"Lễ hội Phủ Dầy",t:"l",d:3,m:3,j:1,g:"tin-nguong",s:"Lễ hội Phủ Dầy diễn ra từ mùng 3 đến mùng 10 tháng 3 âm lịch, chính hội vào mùng 3/3, tại xã Kim Thái, huyện Vụ Bản, Nam Định, thờ Thánh Mẫu Liễu Hạnh, một trong Tứ Bất Tử của tín…"},{id:"le-hoi-quan-the-am-ngu-hanh-son",n:"Lễ hội Quán Thế Âm Ngũ Hành Sơn",t:"l",d:19,m:2,g:"tin-nguong",s:"Lễ hội Phật giáo lớn nhất Đà Nẵng, diễn ra 17 tới 19 tháng Hai âm lịch, chính hội ngày vía Quán Thế Âm đản sinh.",b:2},{id:"le-hoi-ruoc-co-ba-cho-duoc",n:"Lễ hội Rước Cộ Bà Chợ Được",t:"l",d:11,m:1,g:"tin-nguong",p:"Lăng Bà Chợ Được",s:"Lễ hội tri ân Bà Chợ Được, người lập nên chợ và làng Chợ Được. Đêm 11 tháng Giêng có đoàn rước sáu cỗ cộ, dẫn đầu là cộ sắc phong; ban ngày có hát bộ, bài chòi, đua thuyền. Di sản…",b:1},{id:"le-hoi-tay-thien",n:"Lễ hội Tây Thiên",t:"l",d:15,m:2,g:"tin-nguong",p:"Đền Thượng Tây Thiên",s:"Lễ hội ở khu danh thắng Tây Thiên thờ Quốc mẫu Tây Thiên, khai hội rằm tháng Hai âm lịch. Tín ngưỡng thờ Mẫu Tây Thiên là Di sản văn hóa phi vật thể quốc gia từ năm 2020.",a:2},{id:"le-hoi-thanh-tuyen",n:"Lễ hội Thành Tuyên",t:"a",g:"tin-nguong",p:"Quảng trường Nguyễn Tất Thành",s:'Lễ hội Trung thu của tỉnh Tuyên Quang, nổi bật với các mô hình đèn Trung thu khổng lồ do các phường, xã làm và rước qua phố. Năm 2026 có 45 mô hình, đêm hội chủ đề "Lung linh đêm…',y:{2026:"2026-09-20"}},{id:"le-hoi-thap-ba-ponagar",n:"Lễ hội Tháp Bà Ponagar",t:"l",d:23,m:3,j:1,g:"tin-nguong",p:"Di tích Tháp Bà Ponagar",s:"Từ 20 tới 23 tháng Ba âm lịch, lễ hội ở Tháp Bà Ponagar tôn vinh nữ thần Pô Nagar, Mẹ xứ sở của người Chăm, cũng là Thánh Mẫu Thiên Y A Na của người Việt. Có lễ thay y Mẫu, múa…",b:3},{id:"le-hoi-tich-dien-doi-son",n:"Lễ hội Tịch điền Đọi Sơn",t:"l",d:7,m:1,g:"tin-nguong",s:"Lễ hội Tịch điền Đọi Sơn diễn ra ngày 7 tháng Giêng tại xã Đọi Sơn, Duy Tiên, Hà Nam, tái hiện nghi lễ vua Lê Đại Hành xuống ruộng cày đầu năm 987, mang ý nghĩa khuyến khích nông…"},{id:"le-hoi-tien-cong",n:"Lễ hội Tiên Công",t:"l",d:7,m:1,g:"tin-nguong",p:"Miếu Tiên Công",s:"Lễ hội ở miếu Tiên Công tưởng nhớ 17 vị Tiên Công từ Thăng Long về quai đê lấn biển lập nên vùng đảo Hà Nam. Ngày chính hội mùng 7 tháng Giêng có nghi lễ rước người độc đáo: con…",b:2},{id:"le-hoi-tro-tram",n:"Lễ hội Trò Trám",t:"l",d:11,m:1,g:"tin-nguong",p:"Miếu Trò",s:"Lễ hội ở miếu Trò, xã Tứ Xã, Lâm Thao, Phú Thọ, mang tín ngưỡng phồn thực cầu mùa. Lễ Mật diễn ra đêm 11 rạng sáng 12 tháng Giêng; sáng 12 có lễ rước lúa thần tới đền Xa Lộc rồi…",a:1},{id:"le-hoi-truong-yen",n:"Lễ hội Trường Yên (Hoa Lư)",t:"l",d:10,m:3,g:"tin-nguong",s:"Lễ hội ở cố đô Hoa Lư tưởng nhớ vua Đinh Tiên Hoàng và vua Lê Đại Hành, diễn ra 8 tới 10 tháng Ba âm lịch.",b:2},{id:"le-hoi-truyen-thong-den-tran-thuong",n:"Lễ hội truyền thống đền Trần Thương",t:"l",d:15,m:8,g:"tin-nguong",p:"Đền Trần Thương (di tích quốc gia đặc biệt)",s:"Lễ hội tháng Tám gắn với ngày giỗ Hưng Đạo Đại vương 20/8 âm lịch; năm 2026 kỷ niệm 726 năm ngày mất, có Liên hoan thực hành nghi lễ hầu Thánh ngày 26/9.",a:5,y:{2026:"2026-09-26"}},{id:"le-hoi-truyen-thong-van-don",n:"Lễ hội truyền thống Vân Đồn",t:"l",d:18,m:6,g:"tin-nguong",p:"Đình Quan Lạn, miếu Đức Ông",s:"Lễ hội đua bơi ở xã đảo Quan Lạn tưởng nhớ trận Vân Đồn năm 1288, khi quân Trần dưới quyền Trần Khánh Dư đánh tan đoàn thuyền lương nhà Nguyên. Chính hội 18 tháng Sáu có đại tế,…",b:8,a:1},{id:"le-hoi-van-hoa-du-lich-muong-lo",n:"Lễ hội Văn hóa, du lịch Mường Lò",t:"a",g:"khac",p:"Sân vận động Nghĩa Lộ",s:"Lễ hội ở cánh đồng Mường Lò, vùng đất gốc của người Thái đen, với màn đại xòe Thái hàng trăm người, diễu diễn đường phố và hội chợ du lịch Tây Bắc.",y:{2026:"2026-10-02"}},{id:"le-hoi-van-hoa-the-gioi-ha-noi",n:"Lễ hội Văn hóa thế giới tại Hà Nội",t:"a",g:"khac",p:"Hoàng thành Thăng Long",s:"Lễ hội văn hóa quốc tế do Hà Nội tổ chức, quy tụ biểu diễn nghệ thuật, ẩm thực và triển lãm của nhiều quốc gia.",y:{2026:"2026-10-01"}},{id:"le-hoi-via-ba-chua-xu-go-thap",n:"Lễ hội Vía Bà Chúa Xứ Gò Tháp",t:"l",d:15,m:3,g:"tin-nguong",p:"Khu di tích quốc gia đặc biệt Gò Tháp",s:"Lễ vía Bà Chúa Xứ ở khu di tích quốc gia đặc biệt Gò Tháp, phần lễ theo nghi thức tín ngưỡng dân gian truyền thống. Phần hội có hát tuồng, múa bóng rỗi, lân sư rồng, trò chơi dân…",b:1,a:1,y:{2026:"2026-04-30"}},{id:"le-hoi-via-ba-chua-xu-nui-sam",n:"Lễ hội Vía Bà Chúa Xứ Núi Sam",t:"l",d:23,m:4,g:"tin-nguong",s:"Lễ hội tín ngưỡng dân gian lâu đời của cư dân Nam Bộ, tổ chức từ 22-27 tháng 4 âm lịch (chính hội 23-24/4) tại Núi Sam, Châu Đốc để tưởng niệm Bà Chúa Xứ; được UNESCO ghi danh Di…"},{id:"le-hoi-xa-ma-ruoc-kieu-dinh-hoang-chau",n:"Lễ hội Xa Mã, rước kiệu đình Hoàng Châu",t:"l",d:10,m:6,g:"tin-nguong",p:"Đình Hoàng Châu",s:"Lễ hội ở đình Hoàng Châu tưởng nhớ ngày dựng đình, tạ ơn thần biển Nam Hải, Đông Hải và hai vị Thành hoàng, cầu ngư dân ra khơi bình an. Đại tế và đoàn xa mã, rước kiệu chia hai…",b:1,a:2},{id:"le-hoi-xuong-giang",n:"Lễ hội Xương Giang",t:"l",d:5,m:1,g:"tin-nguong",p:"Khu di tích Địa điểm chiến thắng Xương Giang",s:"Lễ hội tại Khu di tích quốc gia đặc biệt Địa điểm chiến thắng Xương Giang, kỷ niệm chiến thắng của nghĩa quân Lam Sơn năm 1427. Hội diễn ra từ mùng 5 tới mùng 7 tháng Giêng, gồm…",a:2},{id:"le-hoi-yen-tu",n:"Lễ hội Yên Tử",t:"l",d:10,m:1,j:1,g:"tin-nguong",s:"Lễ hội Xuân Yên Tử khai hội vào ngày 10 tháng Giêng hằng năm tại Cung Trúc Lâm, mở đầu mùa hành hương về non thiêng Yên Tử, nơi vua Trần Nhân Tông tu hành lập nên Thiền phái Trúc…"},{id:"le-khai-an-den-tran",n:"Lễ Khai ấn Đền Trần",t:"l",d:15,m:1,j:1,g:"tin-nguong",s:"Lễ Khai ấn Đền Trần diễn ra vào đêm 14 rạng sáng 15 tháng Giêng tại Đền Trần, TP Nam Định, tục lệ có từ thời Trần với ý nghĩa cầu quốc thái dân an."},{id:"le-khai-mac-nam-du-lich-quoc-gia",n:"Lễ khai mạc Năm Du lịch quốc gia",t:"a",j:1,g:"khac",p:"Quảng trường Nguyễn Tất Thành",s:"Năm Du lịch quốc gia do Bộ Văn hóa, Thể thao và Du lịch cùng một tỉnh đăng cai tổ chức, mỗi năm một nơi, mở đầu bằng một tuần lễ khai mạc. Năm 2026 do Gia Lai đăng cai với 244 sự…",y:{2026:"2026-03-23"}},{id:"le-khao-le-the-linh-hoang-sa",n:"Lễ Khao lề thế lính Hoàng Sa",t:"l",d:16,m:3,j:1,g:"tin-nguong",p:"Âm Linh Tự và đình làng An Vĩnh",s:"Nghi lễ gần 400 năm của cư dân Lý Sơn tưởng nhớ những người lính Hải đội Hoàng Sa ra đi giữ đảo, với lễ tế tại Âm Linh Tự, đình làng An Vĩnh và nghi thức thả thuyền mô hình ra…",b:1,y:{2026:"2026-05-02"}},{id:"le-ky-yen-ha-dien-dinh-binh-thuy",n:"Lễ Kỳ yên Hạ điền đình Bình Thủy",t:"l",d:14,m:12,g:"tin-nguong",p:"Đình Bình Thủy",s:"Lễ Kỳ yên Hạ điền tháng Chạp là kỳ lễ thứ hai trong năm của đình Bình Thủy, tạ ơn thần khi mùa màng xong. Có cúng Thần Nông, thay khăn sắc thần, lễ túc yết, tế Sơn Quân.",a:1},{id:"le-ky-yen-thuong-dien-dinh-binh-thuy",n:"Lễ Kỳ yên Thượng điền đình Bình Thủy",t:"l",d:15,m:4,g:"tin-nguong",p:"Đình Bình Thủy",s:"Đình Bình Thủy mở hai lễ Kỳ yên mỗi năm: Thượng điền tháng Tư âm lịch lúc bắt đầu vụ, Hạ điền tháng Chạp. Dân làng tế thần, cúng Thần Nông, cầu mưa thuận gió hòa. Lễ hội Kỳ yên…",b:4},{id:"le-mung-com-moi-cua-nguoi-kho-mu-muong-kim",n:"Lễ mừng cơm mới của người Khơ Mú Mường Kim",t:"a",g:"tin-nguong",p:"Bản Thẩm Phé, xã Mường Kim",s:"Người Khơ Mú làm lễ mừng cơm mới khi lúa nương chín, mời tổ tiên ăn cơm mới, tung cốm cầu may rồi nắm tay nhảy điệu Hưn mạy. Năm 2026 lễ được trình diễn trong chương trình Tết Độc…",y:{2026:"2026-09-01"}},{id:"le-mung-com-moi-cua-nguoi-mong-pung-luong",n:"Lễ mừng cơm mới của người Mông Púng Luông",t:"a",g:"tin-nguong",p:"Xã Púng Luông",s:"Theo phong tục, khi lúa chín người Mông nấu cơm từ hạt gạo đầu mùa dâng tổ tiên, rồi mời thần nhà, thần lửa, thần sông, thần núi. Lễ mừng cơm mới của người Mông vùng Mù Cang Chải…",y:{2026:"2026-09-26"}},{id:"le-phat-dan",n:"Lễ Phật Đản",t:"l",d:15,m:4,j:1,g:"tin-nguong",s:"Lễ Phật Đản (Đại lễ Vesak) là ngày kỷ niệm Đức Phật Thích Ca Mâu Ni ra đời, được Phật giáo Việt Nam thống nhất tổ chức vào ngày 15 tháng 4 âm lịch hằng năm."},{id:"le-phat-luong-duc-thanh-tran-den-tran-thuong",n:"Lễ phát lương Đức Thánh Trần đền Trần Thương",t:"l",d:14,m:1,g:"tin-nguong",p:"Đền Trần Thương (di tích quốc gia đặc biệt)",s:"Nghi lễ ở di tích quốc gia đặc biệt đền Trần Thương, Ninh Bình (Hà Nam cũ), diễn ra từ giờ Tý đêm 14 tháng Giêng. Trình tự gồm khai hội, rước kiệu Thánh, rước nước, nhập lương,…",a:1},{id:"le-ra-ha-dang-y-kathina",n:"Lễ ra hạ và mùa dâng y Kathina",t:"a",g:"tin-nguong",p:"Các chùa Phật giáo Nam tông Khmer, ví dụ chùa Muniransay (phường Ninh Kiều) và…",s:"Sau ba tháng an cư mùa mưa, chư tăng Phật giáo Nam tông làm lễ ra hạ vào rằm tháng Chín âm lịch. Trong một tháng sau đó, mỗi chùa chọn một ngày làm lễ dâng y Kathina, một trong…",y:{2026:"2026-10-24"}},{id:"le-sene-dolta",n:"Lễ Sene Dolta",t:"a",g:"le-tet",p:"Các chùa Khmer Nam tông và phum sóc vùng Tây Nam Bộ",s:"Lễ cúng ông bà, báo hiếu tổ tiên của người Khmer Nam Bộ, kéo dài ba ngày. Lễ theo lịch Khmer, vốn đặt tháng nhuận khác âm lịch Việt, nên ngày dương xê dịch cả tháng giữa các năm.",y:{2025:"2025-09-21",2026:"2026-10-11"}},{id:"le-te-am-hon-hue",n:"Lễ tế Âm hồn Huế",t:"l",d:23,m:5,g:"tin-nguong",p:"Đàn Âm hồn",s:"Ngày 23 tháng Năm âm lịch, người Huế cúng tế những quan binh và dân thường tử nạn trong biến cố thất thủ Kinh đô năm 1885. Lễ chính cử hành tại Đàn Âm hồn do triều Nguyễn lập năm…"},{id:"le-that-tich",n:"Lễ Thất tịch",t:"l",d:7,m:7,g:"le-tet",s:"Mùng 7 tháng Bảy âm lịch là ngày tương truyền Ngưu Lang, Chức Nữ gặp nhau trên cầu Ô Thước, mưa ngâu là nước mắt đôi lứa. Ngày này được coi là ngày của tình yêu, nhiều bạn trẻ ăn…"},{id:"le-tuong-niem-phat-hoang-tran-nhan-tong-nhap-niet-ban",n:"Lễ tưởng niệm Phật hoàng Trần Nhân Tông nhập Niết bàn",t:"l",d:1,m:11,g:"tin-nguong",p:"Cung Trúc Lâm Yên Tử; Chùa Ngọa Vân",s:"Phật hoàng Trần Nhân Tông, vị vua lãnh đạo hai cuộc kháng chiến chống Nguyên Mông rồi xuất gia và lập Thiền phái Trúc Lâm, nhập Niết bàn ngày mùng 1 tháng Mười một năm Mậu Thân…",b:1},{id:"le-via-ba-linh-son-thanh-mau",n:"Lễ vía Bà Linh Sơn Thánh Mẫu (núi Bà Đen)",t:"l",d:5,m:5,g:"tin-nguong",s:"Lễ hội tín ngưỡng dân gian thờ Linh Sơn Thánh Mẫu (Bà Đen), tổ chức từ 4-6 tháng 5 âm lịch tại núi Bà Đen với nghi thức tắm Bà, thay áo và lễ vía chính vào ngày 5/5; được công…"},{id:"le-via-duc-phat-a-di-da",n:"Lễ vía Đức Phật A Di Đà",t:"l",d:17,m:11,j:1,g:"tin-nguong",s:"Ngày 17 tháng 11 âm lịch, các chùa Bắc tông làm lễ vía, thắp đèn, dâng hoa đăng; mở đầu mùa Gia hạnh Phổ Hiền kéo tới mồng 8 tháng Chạp."},{id:"le-vu-lan",n:"Lễ Vu Lan",t:"l",d:15,m:7,j:1,g:"le-tet",s:"Lễ báo hiếu cha mẹ, nguồn gốc Phật giáo, có tục cài hoa hồng lên áo."},{id:"lien-hoan-phim-quoc-te-ha-noi",n:"Liên hoan Phim quốc tế Hà Nội",t:"a",g:"khac",p:"Trung tâm Triển lãm Việt Nam (VEC); Trung tâm Chiếu phim Quốc gia",s:"Liên hoan Phim quốc tế Hà Nội (HANIFF) do Bộ VHTTDL và UBND TP Hà Nội tổ chức hai năm một lần, gồm phim dự thi và không dự thi, tọa đàm, chợ dự án làm phim và chiếu phim lưu động…",y:{2026:"2026-11-27"}},{id:"ngay-bao-chi-cach-mang-viet-nam",n:"Ngày Báo chí Cách mạng Việt Nam",t:"s",d:21,m:6,g:"khac",s:"Ngày 21/6 kỷ niệm sự ra đời của báo Thanh Niên do Nguyễn Ái Quốc sáng lập năm 1925, được Bộ Chính trị công nhận là Ngày Báo chí Cách mạng Việt Nam năm 2000."},{id:"ngay-cach-mang-thang-tam",n:"Ngày Cách mạng Tháng Tám",t:"s",d:19,m:8,j:1,g:"khac",s:"Ngày 19/8/1945 nhân dân Hà Nội giành chính quyền, mở đầu thắng lợi của Cách mạng Tháng Tám trên cả nước. Luật Công an nhân dân lấy ngày 19/8 hằng năm làm Ngày truyền thống Công an…"},{id:"ngay-chien-thang-dien-bien-phu",n:"Ngày Chiến thắng Điện Biên Phủ",t:"s",d:7,m:5,j:1,g:"khac",p:"Nghĩa trang liệt sĩ quốc gia A1",s:"Ngày 7/5/1954 quân đội Việt Nam giành thắng lợi ở Điện Biên Phủ, kết thúc 56 ngày đêm chiến dịch. Hằng năm tỉnh Điện Biên dâng hương ở nghĩa trang liệt sĩ A1, Him Lam, Độc Lập,…"},{id:"ngay-dan-so-viet-nam",n:"Ngày Dân số Việt Nam",t:"s",d:26,m:12,g:"khac",s:"Ngày 26/12 được Thủ tướng quy định là Ngày Dân số Việt Nam theo Quyết định 326-TTg ngày 19/5/1997, gắn với Quyết định 216-CP về sinh đẻ có kế hoạch ban hành ngày 26/12/1961."},{id:"ngay-di-san-van-hoa-viet-nam",n:"Ngày Di sản văn hóa Việt Nam",t:"s",d:23,m:11,g:"khac",s:"Ngày 23 tháng 11 là Ngày Di sản văn hóa Việt Nam theo Quyết định 36/2005/QĐ-TTg, chọn theo ngày Chủ tịch Hồ Chí Minh ký Sắc lệnh 65/SL năm 1945, văn bản đầu tiên của Nhà nước về…"},{id:"ngay-doanh-nhan-viet-nam",n:"Ngày Doanh nhân Việt Nam",t:"s",d:13,m:10,g:"khac",s:"Ngày 13/10 được Thủ tướng Phan Văn Khải quy định là Ngày Doanh nhân Việt Nam theo Quyết định 990/QĐ-TTg ngày 20/9/2004, gắn với bức thư Bác Hồ gửi giới công thương ngày 13/10/1945."},{id:"ngay-gia-dinh-viet-nam",n:"Ngày Gia đình Việt Nam",t:"s",d:28,m:6,g:"khac",s:"Ngày 28/6 được Thủ tướng Chính phủ quy định là Ngày Gia đình Việt Nam theo Quyết định 72/2001/QĐ-TTg ngày 4/5/2001, nhằm đề cao trách nhiệm xây dựng gia đình no ấm, bình đẳng,…"},{id:"ngay-giai-phong-mien-nam",n:"Ngày Giải phóng miền Nam, thống nhất đất nước",t:"s",d:30,m:4,h:1,j:1,g:"khac",s:"Kỷ niệm ngày thống nhất đất nước 30/4/1975, ngày nghỉ lễ chính thức theo Bộ luật Lao động."},{id:"ngay-giai-phong-thu-do",n:"Ngày Giải phóng Thủ đô",t:"s",d:10,m:10,g:"khac",s:"Kỷ niệm ngày 10/10/1954, bộ đội Việt Nam tiếp quản Hà Nội sau cuộc kháng chiến chống thực dân Pháp."},{id:"ngay-hoi-dai-doan-ket-toan-dan-toc",n:"Ngày hội Đại đoàn kết toàn dân tộc",t:"s",d:18,m:11,g:"khac",s:"Ngày 18 tháng 11 là Ngày truyền thống Mặt trận Tổ quốc Việt Nam, kỷ niệm ngày thành lập Mặt trận Dân tộc thống nhất Việt Nam (18/11/1930), và là Ngày hội Đại đoàn kết toàn dân…"},{id:"ngay-hoi-mua-vang-ta-leng-huong-lua-giua-non-cao",n:'Ngày hội "Mùa vàng Tả Lèng, Hương lúa giữa non cao"',t:"a",g:"tin-nguong",p:"Bản Tả Lèng",s:"Ngày hội mùa vàng lần đầu ở Tả Lèng, gồm lễ mừng cơm mới của người Mông, thi gặt và tuốt lúa thủ công, trò chơi dân gian giữa ruộng bậc thang.",y:{2026:"2026-09-06"}},{id:"ngay-hoi-mua-vang-tren-cao-duong",n:"Ngày hội Mùa vàng trên Cao Đường",t:"a",g:"tin-nguong",p:"Thôn Cao Đường",s:"Ngày hội mùa lúa chín ở thôn Cao Đường với thi gặt lúa, đánh cù, bắt cá, chạy trên ruộng bậc thang, thổi khèn Mông và hát then.",y:{2026:"2026-09-20"}},{id:"ngay-hoi-van-hoa-dan-toc-mong",n:"Ngày hội Văn hóa dân tộc Mông",t:"a",j:1,g:"khac",p:"Quảng trường 7/5; Phố đi bộ Mường Thanh",s:"Ngày hội do Bộ Văn hóa, Thể thao và Du lịch tổ chức với 11 tỉnh có đông người Mông. Có carnival đường phố và màn trình diễn khèn khoảng 3.000 người, thi đấu thể thao dân tộc, trải…",y:{2026:"2026-10-09"}},{id:"ngay-khuyen-hoc-viet-nam",n:"Ngày Khuyến học Việt Nam",t:"s",d:2,m:10,g:"khac",s:"Ngày 2 tháng 10 hằng năm là Ngày Khuyến học Việt Nam, theo Quyết định 1271/QĐ-TTg ngày 16/9/2008 của Thủ tướng Chính phủ. Ngày này nhằm động viên các tổ chức xã hội và người dân…"},{id:"ngay-moi-truong-the-gioi",n:"Ngày Môi trường Thế giới",t:"s",d:5,m:6,g:"khac",s:"Ngày 5/6 là Ngày Môi trường Thế giới do Liên Hợp Quốc khởi xướng từ năm 1972, Việt Nam chính thức tham gia hưởng ứng từ năm 1982."},{id:"ngay-nam-ky-khoi-nghia",n:"Ngày Nam Kỳ khởi nghĩa",t:"s",d:23,m:11,g:"khac",p:"Khu di tích Nam Kỳ khởi nghĩa (đình Long Hưng)",s:"Đêm 22 rạng sáng 23 tháng 11 năm 1940, khởi nghĩa Nam Kỳ nổ ra ở nhiều tỉnh, trong đó có Mỹ Tho, và lá cờ đỏ sao vàng lần đầu xuất hiện tại đình Long Hưng. Hằng năm vào ngày…"},{id:"ngay-nguoi-khuyet-tat-viet-nam",n:"Ngày Người khuyết tật Việt Nam",t:"s",d:18,m:4,g:"khac",s:"Ngày 18/4 được quy định là Ngày Người khuyết tật Việt Nam, ban đầu theo Pháp lệnh số 06/1998/PL-UBTVQH10, sau đó chính thức hóa tại Điều 11 Luật Người khuyết tật (Luật số…"},{id:"ngay-nha-giao-viet-nam",n:"Ngày Nhà giáo Việt Nam",t:"s",d:20,m:11,j:1,g:"khac",s:"Ngày 20/11 là ngày truyền thống tôn vinh nhà giáo Việt Nam, được Hội đồng Bộ trưởng chính thức công nhận theo Quyết định 167/HĐBT ngày 28/9/1982."},{id:"ngay-phap-luat-viet-nam",n:"Ngày Pháp luật Việt Nam",t:"s",d:9,m:11,g:"khac",s:"Ngày 9 tháng 11 là Ngày Pháp luật nước Cộng hòa xã hội chủ nghĩa Việt Nam, lấy theo ngày Quốc hội thông qua bản Hiến pháp đầu tiên năm 1946, và được quy định trong Luật Phổ biến,…"},{id:"ngay-phu-nu-viet-nam",n:"Ngày Phụ nữ Việt Nam",t:"s",d:20,m:10,j:1,g:"khac",s:"Ngày 20/10 đánh dấu sự kiện thành lập Hội Phụ nữ phản đế Việt Nam (tiền thân của Hội Liên hiệp Phụ nữ Việt Nam) ngày 20/10/1930, được chọn làm ngày truyền thống của phụ nữ Việt…"},{id:"ngay-quoc-te-nguoi-cao-tuoi",n:"Ngày Quốc tế Người cao tuổi",t:"s",d:1,m:10,g:"khac",s:'Ngày 1/10 là Ngày Quốc tế Người cao tuổi do Liên Hợp Quốc công bố năm 1990, Việt Nam hưởng ứng từ năm 1991 và gắn với "Tháng hành động vì Người cao tuổi" theo Quyết định…'},{id:"ngay-quoc-te-phu-nu",n:"Ngày Quốc tế Phụ nữ",t:"s",d:8,m:3,j:1,g:"khac",s:"Ngày 8/3 là Ngày Quốc tế Phụ nữ được tổ chức trên toàn thế giới, ở Việt Nam còn gắn với sự kiện khởi nghĩa Hai Bà Trưng."},{id:"ngay-quoc-te-thieu-nhi",n:"Ngày Quốc tế Thiếu nhi",t:"s",d:1,m:6,j:1,g:"khac",s:"Ngày 1/6 là Ngày Quốc tế Thiếu nhi, được Việt Nam hưởng ứng từ năm 1950 khi Chủ tịch Hồ Chí Minh gửi thư chúc mừng thiếu nhi cả nước."},{id:"ngay-sach-va-van-hoa-doc-viet-nam",n:"Ngày Sách và Văn hóa đọc Việt Nam",t:"s",d:21,m:4,g:"khac",s:"Ngày 21/4 được Thủ tướng quy định là Ngày Sách Việt Nam theo Quyết định 284/QĐ-TTg (2014), đổi tên thành Ngày Sách và Văn hóa đọc Việt Nam theo Quyết định 1862/QĐ-TTg (2021); ngày…"},{id:"ngay-san-khau-viet-nam-va-le-gio-to-san-khau",n:"Ngày Sân khấu Việt Nam và lễ Giỗ Tổ sân khấu",t:"l",d:12,m:8,j:1,g:"tin-nguong",p:"Cung Văn hóa Lao động Hữu nghị Việt Xô",s:"Quyết định 13/QĐ-TTg năm 2011 lấy 12 tháng 8 âm lịch làm Ngày Sân khấu Việt Nam; năm 2026 Hội Nghệ sĩ Sân khấu Việt Nam tổ chức lễ lần thứ XVII ngày 19/9 tại Hà Nội với gần 1.000…",y:{2026:"2026-09-19"}},{id:"ngay-sinh-chu-tich-ho-chi-minh",n:"Ngày sinh Chủ tịch Hồ Chí Minh",t:"s",d:19,m:5,j:1,g:"khac",s:"Ngày 19/5/1890 là ngày sinh Chủ tịch Hồ Chí Minh (tên khai sinh Nguyễn Sinh Cung) tại làng Sen, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An."},{id:"ngay-thanh-lap-dang-cong-san-viet-nam",n:"Ngày thành lập Đảng Cộng sản Việt Nam",t:"s",d:3,m:2,j:1,g:"khac",s:"Ngày 3/2/1930, Hội nghị hợp nhất các tổ chức cộng sản do Nguyễn Ái Quốc chủ trì tại Hong Kong đã thành lập Đảng Cộng sản Việt Nam."},{id:"ngay-thanh-lap-doan-tncs-ho-chi-minh",n:"Ngày thành lập Đoàn TNCS Hồ Chí Minh",t:"s",d:26,m:3,g:"khac",s:"Ngày 26/3/1931 được Đại hội Đoàn toàn quốc lần thứ III (1961) chọn làm ngày thành lập Đoàn Thanh niên Cộng sản Hồ Chí Minh, gắn với Hội nghị Ban Chấp hành Trung ương Đảng lần thứ…"},{id:"ngay-thanh-lap-quan-doi-nhan-dan-viet-nam",n:"Ngày thành lập Quân đội Nhân dân Việt Nam",t:"s",d:22,m:12,j:1,g:"khac",s:"Ngày 22/12/1944, Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập tại Cao Bằng, đánh dấu sự ra đời của Quân đội Nhân dân Việt Nam; từ 1989 ngày này cũng là Ngày hội Quốc…"},{id:"ngay-thay-thuoc-viet-nam",n:"Ngày Thầy thuốc Việt Nam",t:"s",d:27,m:2,g:"khac",s:"Ngày 27/2 gắn với bức thư Chủ tịch Hồ Chí Minh gửi ngành y tế năm 1955, được Hội đồng Bộ trưởng công nhận là Ngày Thầy thuốc Việt Nam theo quyết định ngày 6/2/1985."},{id:"ngay-thuong-binh-liet-si",n:"Ngày Thương binh Liệt sĩ",t:"s",d:27,m:7,j:1,g:"khac",s:"Ngày 27/7 hằng năm là ngày tri ân thương binh, bệnh binh và liệt sĩ đã hy sinh, cống hiến cho sự nghiệp đấu tranh giải phóng và bảo vệ Tổ quốc, được xác lập từ năm 1947."},{id:"ngay-toan-quoc-khang-chien",n:"Ngày Toàn quốc kháng chiến",t:"s",d:19,m:12,g:"khac",s:"Kỷ niệm ngày 19/12/1946, khi Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến chống thực dân Pháp."},{id:"ngay-van-hoa-viet-nam",n:"Ngày Văn hóa Việt Nam",t:"s",d:24,m:11,h:1,j:1,g:"le-tet",s:"Ngày Văn hóa Việt Nam 24/11, người lao động được nghỉ làm việc và hưởng nguyên lương theo Nghị quyết 28/2026/QH16 (hiệu lực từ 01/7/2026).",fy:2026},{id:"quoc-khanh",n:"Quốc khánh",t:"s",d:2,m:9,h:1,j:1,g:"khac",s:"Ngày Quốc khánh nước Cộng hòa Xã hội Chủ nghĩa Việt Nam 2/9, ngày nghỉ lễ chính thức theo Bộ luật Lao động."},{id:"quoc-te-lao-dong",n:"Ngày Quốc tế Lao động",t:"s",d:1,m:5,h:1,j:1,g:"khac",s:"Ngày Quốc tế Lao động 1/5, ngày nghỉ lễ chính thức theo Bộ luật Lao động."},{id:"ram-thang-gieng",n:"Rằm tháng Giêng (Tết Nguyên Tiêu)",t:"l",d:15,m:1,j:1,g:"le-tet",s:"Ngày rằm đầu tiên của năm âm lịch, dịp đi lễ chùa cầu an đầu năm."},{id:"tet-chol-chnam-thmay",n:"Tết Chôl Chnăm Thmây",t:"s",d:14,m:4,g:"le-tet",s:"Tết cổ truyền lớn nhất trong năm của người Khmer Nam Bộ, bắt nguồn từ Phật giáo Nam tông, diễn ra vào giữa tháng 4 dương lịch (không theo âm lịch Việt, ngày cụ thể có thể lệch 1…"},{id:"tet-com-moi-cua-nguoi-muong",n:"Tết cơm mới của người Mường",t:"l",d:10,m:10,g:"le-tet",p:"Đình Khoang, xóm Khoang",s:"Người Mường ở Hương Cần làm Tết cơm mới ngày 10 tháng 10 âm lịch để kết thúc vụ mùa, tạ ơn trời đất, tổ tiên và người lập làng, có diễn tấu cồng chiêng và hát ví."},{id:"tet-com-moi-cua-nguoi-tay",n:"Tết cơm mới của người Tày",t:"l",d:10,m:10,g:"le-tet",p:"Khu bảo tồn làng văn hóa các dân tộc Thái Hải; Các thôn người Tày",s:"Một trong sáu cái Tết của người Tày, làm đúng ngày 10 tháng 10 âm lịch sau vụ gặt để dâng cơm mới, xôi ngũ sắc, bánh dày lên trời đất và tổ tiên."},{id:"tet-doan-ngo",n:"Tết Đoan Ngọ",t:"l",d:5,m:5,j:1,g:"le-tet",s:"Ngày diệt sâu bọ theo quan niệm dân gian, ăn rượu nếp và trái cây chua vào sáng sớm."},{id:"tet-duong-lich",n:"Tết Dương Lịch",t:"s",d:1,m:1,h:1,j:1,g:"khac",s:"Ngày đầu năm mới theo dương lịch, 1 trong 6 dịp nghỉ lễ chính thức theo Bộ luật Lao động."},{id:"tet-ha-nguyen",n:"Tết Hạ Nguyên",t:"l",d:15,m:10,j:1,g:"le-tet",s:"Rằm tháng 10 âm lịch, một trong bốn tết theo mùa, dịp tạ ơn trời đất sau vụ mùa."},{id:"tet-han-thuc",n:"Tết Hàn Thực",t:"l",d:3,m:3,g:"le-tet",s:"Ngày cúng bánh trôi bánh chay, tưởng nhớ tổ tiên theo phong tục cổ truyền."},{id:"tet-nguyen-dan",n:"Tết Nguyên Đán",t:"l",d:1,m:1,h:1,j:1,g:"le-tet",s:"Ngày đầu năm mới âm lịch, lễ lớn nhất trong năm của người Việt, dịp sum họp gia đình và cúng gia tiên."},{id:"tet-ong-cong-ong-tao",n:"Tết ông Công ông Táo",t:"l",d:23,m:12,j:1,g:"le-tet",s:"Ngày tiễn ông Công ông Táo về trời báo cáo việc gia đình trong năm."},{id:"tet-trung-cuu",n:"Tết Trùng Cửu (Trùng Dương)",t:"l",d:9,m:9,g:"le-tet",s:"Ngày chín tháng Chín âm lịch, hai số dương gặp nhau. Tục cổ lên cao, uống rượu hoa cúc, cầu sống lâu; ngày nay ở Việt Nam ít nơi còn giữ."},{id:"tet-trung-thap",n:"Tết Trùng Thập",t:"l",d:10,m:10,j:1,g:"le-tet",s:"Mồng 10 tháng 10 âm lịch, khi vừa xong vụ mùa, nhà nông nấu cơm gạo mới, làm bánh giầy cúng gia tiên; giới đông y coi là tết của thầy thuốc vì cây thuốc tụ khí tốt nhất."},{id:"tet-trung-thu",n:"Tết Trung Thu",t:"l",d:15,m:8,j:1,g:"le-tet",s:"Tết thiếu nhi, rước đèn phá cỗ, ăn bánh trung thu dưới trăng rằm tháng 8."},{id:"tet-xip-xi-cua-nguoi-thai-trang",n:"Tết Xíp xí của người Thái trắng",t:"l",d:14,m:7,g:"le-tet",p:"Cộng đồng người Thái trắng Quỳnh Nhai, Phù Yên",s:"Tết của người Thái trắng ở Quỳnh Nhai và Phù Yên (Sơn La) vào ngày 14 tháng Bảy âm lịch, chỉ một ngày, có khi chỉ một bữa trưa. Mâm cúng tổ tiên có vịt, gà, thịt lợn hun khói, cá…"},{id:"tuan-du-lich-ninh-binh",n:"Tuần Du lịch Ninh Bình",t:"a",g:"khac",p:"Quảng trường Đinh Tiên Hoàng Đế; Khu du lịch Tam Cốc - Bích Động",s:"Tuần lễ du lịch của tỉnh Ninh Bình vào mùa lúa chín trên cánh đồng Tam Cốc, gắn với thương hiệu Sắc vàng Tam Cốc - Tràng An. Có chương trình nghệ thuật khai mạc, lễ rước sản vật,…",y:{2026:"2026-05-23"}},{id:"tuan-le-festival-nghe-thuat-quoc-te-hue",n:"Tuần lễ Festival Nghệ thuật quốc tế Huế",t:"a",j:1,g:"khac",p:"Đại Nội Huế",s:"Tuần lễ nghệ thuật quốc tế, điểm nhấn của Festival Huế, quy tụ đoàn nghệ thuật trong nước và nước ngoài biểu diễn tại Đại Nội và các sân khấu đường phố. Từ năm 2026, Festival Huế…",y:{2026:"2026-06-13"}},{id:"tuan-van-hoa-du-lich-moc-chau",n:"Tuần Văn hóa, Du lịch Mộc Châu",t:"a",g:"khac",p:"Quảng trường 8/5",s:'Lần đầu tổ chức ở cấp tỉnh, phát triển từ Ngày hội văn hóa dân tộc Mông Mộc Châu, chủ đề "Dệt di sản, hòa giao sắc màu". Có trại văn hóa của 13 xã phường và màn ném pao 200 nghệ…',y:{2026:"2026-08-31"}},{id:"tuan-van-hoa-the-thao-va-du-lich-xa-hoang-su-phi",n:"Tuần Văn hóa, Thể thao và Du lịch xã Hoàng Su Phì",t:"a",g:"tin-nguong",p:"Trung tâm xã Hoàng Su Phì và các thôn",s:'Tuần văn hóa mùa lúa chín trên danh thắng ruộng bậc thang Hoàng Su Phì, chủ đề "Hoàng Su Phì: Hội tụ sắc màu văn hóa, khơi nguồn phát triển". Có tái hiện nghi lễ của một số dân…',y:{2026:"2026-09-18"}},{id:"via-ba-thien-hau-cho-lon",n:"Vía Bà Thiên Hậu Chợ Lớn",t:"l",d:23,m:3,g:"tin-nguong",p:"Chùa Bà Thiên Hậu (hội quán Tuệ Thành)",s:"Ngày 23 tháng Ba âm lịch là vía Bà Thiên Hậu, ngày hội chính của chùa Bà Thiên Hậu (hội quán Tuệ Thành) do người Hoa gốc Quảng Châu dựng ở Chợ Lớn. Sáng 23 có lễ rước kiệu Bà qua…"},{id:"via-quan-thanh-de-quan",n:"Vía Quan Thánh Đế Quân",t:"l",d:24,m:6,g:"tin-nguong",p:"Chùa Ông (hội quán Nghĩa An)",s:"Ngày 24 tháng Sáu âm lịch được xem là ngày sinh và hiển thánh của Quan Công, một trong hai lễ lớn nhất ở chùa Ông (hội quán Nghĩa An) Chợ Lớn. Cộng đồng người Hoa và người Việt…"},{id:"via-quan-the-am-dan-sinh",n:"Vía Quán Thế Âm Bồ Tát đản sinh",t:"l",d:19,m:2,g:"tin-nguong",s:"Ngày 19 tháng Hai âm lịch, một trong ba ngày vía Quán Thế Âm trong năm. Chùa làm lễ, Phật tử đi lễ và ăn chay."},{id:"via-quan-the-am-thanh-dao",n:"Vía Quán Thế Âm Bồ Tát thành đạo",t:"l",d:19,m:6,g:"tin-nguong",s:"Ngày 19 tháng Sáu âm lịch, một trong ba ngày vía Quán Thế Âm trong năm."},{id:"via-quan-the-am-xuat-gia",n:"Vía Quán Thế Âm Bồ Tát xuất gia",t:"l",d:19,m:9,g:"tin-nguong",s:"Ngày 19 tháng Chín âm lịch, một trong ba ngày vía Quán Thế Âm trong năm."}];"undefined"!=typeof module&&(module.exports=FESTIVALS);